#!/usr/bin/env bash
set -euo pipefail

require_cmd() {
  command -v "$1" >/dev/null 2>&1 || {
    echo "missing required command: $1" >&2
    exit 1
  }
}

require_env() {
  local name="$1"
  if [ -z "${!name:-}" ]; then
    echo "missing required env: $name" >&2
    exit 1
  fi
}

require_cmd docker
docker compose version >/dev/null 2>&1 || {
  echo "docker compose plugin not available" >&2
  exit 1
}

for var in POSTGRES_PASSWORD RWFW__MAIL__SMTP_HOST RWFW__MAIL__SMTP_USERNAME RWFW__MAIL__SMTP_PASSWORD; do
  require_env "$var"
done

echo "preflight ok"
